func TestListImagesOrderAndShape(t *testing.T) {
	e := setup(t)
	set := filepath.Join(e.datasets, "set")
	for _, f := range []string{"img10.png", "img2.PNG", "Img1.jpg", "img_1.webp", "notes.txt", ".hidden.png",
		"sub/b.mp4", "sub/a.wav", "_controls/c.png", ".dot/d.png", "img1.png"} {
		touch(t, filepath.Join(set, filepath.FromSlash(f)), "x")
	}
	rec := e.postJSON(t, "/api/datasets/listImages", `{"datasetName":"set"}`)
	wantStatus(t, rec, 200, "")
	if ce := rec.Header().Get("Content-Encoding"); ce != "" {
		t.Fatalf("unexpected Content-Encoding %q", ce)
	}
	sep := string(filepath.Separator)
	wantBody := map[string]any{
		"root":   set + sep,
		"images": []any{"img_1.webp", "Img1.jpg", "img1.png", "img10.png", "img2.PNG", "sub" + sep + "a.wav", "sub" + sep + "b.mp4"},
	}
	var got map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &got); err != nil {
		t.Fatal(err)
	}
	gb, _ := json.Marshal(got)
	wb, _ := json.Marshal(wantBody)
	if !bytes.Equal(gb, wb) {
		t.Fatalf("got %s\nwant %s", gb, wb)
	}
	if !strings.HasPrefix(rec.Body.String(), `{"root":`) {
		t.Fatalf("root must come first: %s", rec.Body.String())
	}

	// brotli wins when offered, like upstream
	rec = e.do(t, http.MethodPost, "/api/datasets/listImages", strings.NewReader(`{"datasetName":"set"}`),
		http.Header{"Accept-Encoding": {"gzip, deflate, br"}})
	if rec.Header().Get("Content-Encoding") != "br" {
		t.Fatalf("want br, got %q", rec.Header().Get("Content-Encoding"))
	}
	plain, _ := io.ReadAll(brotli.NewReader(rec.Body))
	if !bytes.Equal(plain, gb) && !json.Valid(plain) {
		t.Fatalf("bad brotli payload %s", plain)
	}

	rec = e.do(t, http.MethodPost, "/api/datasets/listImages", strings.NewReader(`{"datasetName":"set"}`),
		http.Header{"Accept-Encoding": {"gzip, deflate"}})
	if rec.Header().Get("Content-Encoding") != "gzip" {
		t.Fatalf("want gzip, got %q", rec.Header().Get("Content-Encoding"))
	}
	zr, err := gzip.NewReader(rec.Body)
	if err != nil {
		t.Fatal(err)
	}
	plain, _ = io.ReadAll(zr)
	if !bytes.Equal(plain, gb) && !json.Valid(plain) {
		t.Fatalf("bad gzip payload %s", plain)
	}
}

func TestListImagesRejectsTraversal(t *testing.T) {
	e := setup(t)
	os.MkdirAll(filepath.Join(e.datasets, "set"), 0o755)
	outside := filepath.Join(filepath.Dir(e.datasets), "outside")
	os.MkdirAll(outside, 0o755)
	for _, name := range []string{`""`, `"   "`, `".."`, `"../outside"`, `"set/../../outside"`, `"set/sub"`, `"."`,
		mustJSON(outside), `5`, `null`} {
		wantStatus(t, e.postJSON(t, "/api/datasets/listImages", `{"datasetName":`+name+`}`), 400, `{"error":"Invalid dataset name"}`)
	}
	wantStatus(t, e.postJSON(t, "/api/datasets/listImages", `[]`), 400, `{"error":"Invalid dataset name"}`)
	wantStatus(t, e.postJSON(t, "/api/datasets/listImages", `{"datasetName":"nope"}`), 404, `{"error":"Folder 'nope' not found"}`)
	wantStatus(t, e.postJSON(t, "/api/datasets/listImages", `not json`), 500, "")
}

func mustJSON(v any) string {
	b, _ := json.Marshal(v)
	return string(b)
}

type part struct {
	field, filename, data string
	file                  bool
}

func multipartBody(t *testing.T, parts []part) (io.Reader, string) {
	t.Helper()
	var buf bytes.Buffer
	mw := multipart.NewWriter(&buf)
	for _, p := range parts {
		h := textproto.MIMEHeader{}
		if p.file {
			h.Set("Content-Disposition", `form-data; name="`+p.field+`"; filename="`+p.filename+`"`)
			h.Set("Content-Type", "application/octet-stream")
		} else {
			h.Set("Content-Disposition", `form-data; name="`+p.field+`"`)
		}
		w, err := mw.CreatePart(h)
		if err != nil {
			t.Fatal(err)
		}
		io.WriteString(w, p.data)
	}
	mw.Close()
	return &buf, mw.FormDataContentType()
}

func TestUploadSanitizesNamesAndPaths(t *testing.T) {
	e := setup(t)
	body, ct := multipartBody(t, []part{
		{field: "files", filename: "../evil name?.png", data: "one", file: true},
		{field: "files", filename: "dir/sub\\x 😀.jpg", data: "two", file: true},
		{field: "datasetName", data: "my set"},
	})
	rec := e.do(t, http.MethodPost, "/api/datasets/upload", body, http.Header{"Content-Type": {ct}})
	wantStatus(t, rec, 200, `{"message":"Files uploaded successfully","files":[".._evil_name_.png","dir_sub_x___.jpg"]}`)
	for name, data := range map[string]string{".._evil_name_.png": "one", "dir_sub_x___.jpg": "two"} {
		got, err := os.ReadFile(filepath.Join(e.datasets, "my set", name))
		if err != nil || string(got) != data {
			t.Fatalf("%s: %q %v", name, got, err)
		}
	}
	if _, err := os.Stat(filepath.Join(e.datasets, "evil name?.png")); err == nil {
		t.Fatal("file escaped the dataset folder")
	}

	for _, ds := range []string{"..", "../x", "a/b", "", "  "} {
		body, ct := multipartBody(t, []part{{field: "files", filename: "a.png", data: "x", file: true}, {field: "datasetName", data: ds}})
		wantStatus(t, e.do(t, http.MethodPost, "/api/datasets/upload", body, http.Header{"Content-Type": {ct}}), 400, `{"error":"Invalid dataset name"}`)
	}
	body, ct = multipartBody(t, []part{{field: "files", filename: "a.png", data: "x", file: true}})
	wantStatus(t, e.do(t, http.MethodPost, "/api/datasets/upload", body, http.Header{"Content-Type": {ct}}), 400, `{"error":"Invalid dataset name"}`)
	body, ct = multipartBody(t, []part{{field: "datasetName", data: "set"}})
	wantStatus(t, e.do(t, http.MethodPost, "/api/datasets/upload", body, http.Header{"Content-Type": {ct}}), 400, `{"error":"No files provided"}`)
	wantStatus(t, e.postJSON(t, "/api/datasets/upload", `{}`), 500, `{"error":"Error uploading files"}`)
}

func TestCreateAndDelete(t *testing.T) {
	e := setup(t)
	os.MkdirAll(e.datasets, 0o755)
	wantStatus(t, e.postJSON(t, "/api/datasets/create", `{"name":"My  Set!! v2"}`), 200, `{"success":true,"name":"my_set_v2"}`)
	if st, err := os.Stat(filepath.Join(e.datasets, "my_set_v2")); err != nil || !st.IsDir() {
		t.Fatal("dataset folder not created")
	}
	wantStatus(t, e.postJSON(t, "/api/datasets/create", `{"name":"../../etc"}`), 200, `{"success":true,"name":"_etc"}`)
	wantStatus(t, e.postJSON(t, "/api/datasets/create", `{"name":5}`), 500, `{"error":"Failed to create dataset"}`)

	touch(t, filepath.Join(e.datasets, "my_set_v2", "a.png"), "x")
	outside := filepath.Join(filepath.Dir(e.datasets), "keep")
	os.MkdirAll(outside, 0o755)
	for _, name := range []string{`".."`, `"../keep"`, mustJSON(outside), `""`, `"."`} {
		wantStatus(t, e.postJSON(t, "/api/datasets/delete", `{"name":`+name+`}`), 400, `{"error":"Invalid dataset name"}`)
	}
	if _, err := os.Stat(outside); err != nil {
		t.Fatal("delete escaped the datasets root")
	}
	wantStatus(t, e.postJSON(t, "/api/datasets/delete", `{"name":"missing"}`), 200, `{"success":true}`)
	wantStatus(t, e.postJSON(t, "/api/datasets/delete", `{"name":"my_set_v2"}`), 200, `{"success":true}`)
	if _, err := os.Stat(filepath.Join(e.datasets, "my_set_v2")); err == nil {
		t.Fatal("dataset not deleted")
	}
}

func TestListLoras(t *testing.T) {
	e := setup(t)
	ctx := context.Background()
	if _, err := store.CreateJob(ctx, store.NewJob{Name: "job1", GpuIDs: "0", JobConfig: "{}"}); err != nil {
		t.Fatal(err)
	}
	if _, err := store.CreateJob(ctx, store.NewJob{Name: "empty", GpuIDs: "0", JobConfig: "{}"}); err != nil {
		t.Fatal(err)
	}
	old := filepath.Join(e.training, "job1", "old.safetensors")
	touch(t, old, "aa")
	os.Chtimes(old, time.Now().Add(-time.Hour), time.Now().Add(-time.Hour))
	touch(t, filepath.Join(e.training, "job1", "new.safetensors"), "bbb")
	touch(t, filepath.Join(e.training, "job1", "x.ckpt"), "c")
	touch(t, filepath.Join(e.models, "loras", "b", "z.safetensors"), "1")
	touch(t, filepath.Join(e.models, "loras", "A.safetensors"), "1")
	touch(t, filepath.Join(e.models, "loras", ".uploads", "p.safetensors"), "1")

	rec := e.do(t, http.MethodGet, "/api/loras", nil, nil)
	wantStatus(t, rec, 200, "")
	var got struct {
		Jobs []struct {
			Name  string
			Files []loraFile
		}
		Models    []modelLora
		LorasRoot string
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &got); err != nil {
		t.Fatal(err)
	}
	if len(got.Jobs) != 1 || got.Jobs[0].Name != "job1" || len(got.Jobs[0].Files) != 2 ||
		got.Jobs[0].Files[0].Name != "new.safetensors" || got.Jobs[0].Files[1].Size != 2 {
		t.Fatalf("jobs: %+v", got.Jobs)
	}
	if len(got.Models) != 2 || got.Models[0].Relpath != "A.safetensors" || got.Models[1].Relpath != filepath.Join("b", "z.safetensors") {
		t.Fatalf("models: %+v", got.Models)
	}
	if got.LorasRoot != filepath.Join(e.models, "loras") {
		t.Fatalf("lorasRoot %s", got.LorasRoot)
	}
}

func TestLoraUploadFlow(t *testing.T) {
	e := setup(t)
	post := func(q string, body string) *httptest.ResponseRecorder {
		return e.do(t, http.MethodPost, "/api/loras/upload?"+q, strings.NewReader(body), nil)
	}
	wantStatus(t, post("action=start&fileName=bad.bin&size=4", ""), 400, `{"error":"File must be a .safetensors file"}`)
	wantStatus(t, post("action=start&fileName=.safetensors&size=4", ""), 400, `{"error":"File must be a .safetensors file"}`)
	wantStatus(t, post("action=start&fileName=my.safetensors&size=0", ""), 400, `{"error":"Invalid file size"}`)

	rec := post("action=start&fileName=sub/my%20lora.safetensors&size=4", "")
	wantStatus(t, rec, 200, "")
	var start struct{ UploadID, FileName string }
	json.Unmarshal(rec.Body.Bytes(), &start)
	if start.FileName != "sub_my lora.safetensors" || !uuidRe.MatchString(start.UploadID) {
		t.Fatalf("start: %s", rec.Body.String())
	}
	id := start.UploadID
	wantStatus(t, post("action=chunk&uploadId=nope&offset=0", "ab"), 400, `{"error":"Invalid uploadId"}`)
	wantStatus(t, post("action=chunk&uploadId="+id+"&offset=-1", "ab"), 400, `{"error":"Invalid offset"}`)
	wantStatus(t, post("action=chunk&uploadId="+id+"&offset=0", ""), 400, `{"error":"Empty chunk"}`)
	wantStatus(t, post("action=chunk&uploadId="+id+"&offset=2", "cd"), 200, `{"received":2}`)
	wantStatus(t, post("action=chunk&uploadId="+id, "ab"), 200, `{"received":2}`) // missing offset is Number(null) = 0
	name := "sub_my%20lora.safetensors"
	wantStatus(t, post("action=finish&uploadId="+id+"&fileName="+name+"&size=5", ""), 400, `{"error":"Upload incomplete: got 4 of 5 bytes"}`)
	wantStatus(t, post("action=finish&uploadId="+id+"&fileName="+name+"&size=4", ""), 404, `{"error":"Upload not found or expired"}`)

	rec = post("action=start&fileName=good.safetensors&size=4", "")
	json.Unmarshal(rec.Body.Bytes(), &start)
	wantStatus(t, post("action=chunk&uploadId="+start.UploadID+"&offset=0", "abcd"), 200, `{"received":4}`)
	rec = post("action=finish&uploadId="+start.UploadID+"&fileName=good.safetensors&size=4", "")
	dest := filepath.Join(e.models, "loras", "good.safetensors")
	wantStatus(t, rec, 200, `{"path":`+mustJSON(dest)+`,"name":"good.safetensors","size":4}`)
	if b, _ := os.ReadFile(dest); string(b) != "abcd" {
		t.Fatalf("dest content %q", b)
	}
	wantStatus(t, post("action=start&fileName=good.safetensors&size=4", ""), 409, `{"error":"A file with that name already exists","exists":true}`)
	wantStatus(t, post("action=start&fileName=good.safetensors&size=4&overwrite=1", ""), 200, "")
	wantStatus(t, post("action=cancel&uploadId="+start.UploadID, ""), 200, `{"ok":true}`)
	wantStatus(t, post("action=bogus&uploadId="+start.UploadID, ""), 400, `{"error":"Unknown action"}`)
	wantStatus(t, post("action=bogus", ""), 400, `{"error":"Invalid uploadId"}`)
}
